'use strict';
const $=id=>document.getElementById(id);
let catalog={}, active=null, serial=0;
const systems={open_ground:['Open field + ground','Ambient weather','Rain, cold and heat remain outdoor exposures.','Native or amended soil','Mapped soil is a screening layer. Drainage and field tests remain necessary.','Water supply','Dry spells do not account for irrigation or root-zone storage.'],open_pots:['Open field + pots','Fruit exposure remains','Pots do not stop rain reaching berries or remove cold exposure.','Managed substrate','Native-soil chemistry is not the pot root zone. Substrate pH, aeration and drainage must be specified.','Irrigation dependence','Small root-zone storage, water quality and root heating need assessment.'],tunnel_ground:['Tunnel + ground','Potential rain interception','An effective cover can reduce direct fruit wetting; no calibrated numerical reduction is applied.','Heat, light and cold','Ventilation and cover transmission matter. An unheated tunnel does not guarantee frost protection.','Ground constraints remain','Runoff, drainage and native or amended soil still need assessment.'],tunnel_pots:['Tunnel + pots','Cover + managed root zone','Potential rain interception and substrate control are separate effects, not universal protection.','Remaining exposures','Heat, humidity, light loss and cold remain conditional on the actual structure.','Water and drainage','Reliable irrigation, suitable water chemistry and freely draining containers are essential.']};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const good=a=>a.filter(v=>typeof v==='number'&&Number.isFinite(v));
const mean=a=>{a=good(a);return a.length?a.reduce((s,v)=>s+v,0)/a.length:null};
const median=a=>{a=good(a).sort((x,y)=>x-y);return a.length?(a[Math.floor((a.length-1)/2)]+a[Math.floor(a.length/2)])/2:null};
const fmt=(v,d=1)=>v===null||v===undefined?'Unavailable':Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
function card(title,value,unit,desc,values,index){const a=good(values);return `<article class="risk"><div class="risk-top"><h3>${title}</h3><span class="risk-index">0${index}</span></div><div class="metric">${fmt(value)}${value===null?'':`<small>${unit}</small>`}</div><p>${desc}</p><div class="detail">${a.length?`${a.length}/15 valid years · range ${fmt(Math.min(...a))}–${fmt(Math.max(...a))}`:'Not acquired for this coordinate'}</div></article>`}
function bars(id,values,labels,unit){const node=$(id);const w=Math.max(290,node.clientWidth),h=220,p={l:48,r:10,t:16,b:34},valid=good(values);if(!valid.length){node.innerHTML='<p class="small">This metric is unavailable. No values have been substituted.</p>';return}const lo=Math.min(0,...valid),hi=Math.max(...valid,1),y=v=>h-p.b-(v-lo)/(hi-lo)*(h-p.b-p.t),step=(w-p.l-p.r)/values.length;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(unit)} by ${id==='monthly-chart'?'month':'year'}"><title>${esc(unit)}; exact values available in the data tables or JSON export</title>`;for(let n=0;n<=3;n++){const v=lo+(hi-lo)*n/3;svg+=`<line x1="${p.l}" x2="${w-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#ebebeb"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end">${fmt(v,0)}</text>`}values.forEach((v,i)=>{const x=p.l+step*i;if(v!==null&&Number.isFinite(v))svg+=`<rect class="bar" x="${x+step*.16}" width="${step*.68}" y="${Math.min(y(0),y(v))}" height="${Math.max(1,Math.abs(y(v)-y(0)))}"><title>${labels[i]}: ${fmt(v,2)} ${esc(unit)}</title></rect>`;if(i%Math.ceil(labels.length/(w<400?6:12))===0)svg+=`<text x="${x+step/2}" y="${h-10}" text-anchor="middle">${labels[i]}</text>`});node.innerHTML=svg+'</svg>'}
function charts(){if(!active)return;const m=$('monthly-metric').value,a=$('annual-metric').value;bars('monthly-chart',active.climatology[m],['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'],$('monthly-metric').selectedOptions[0].text);bars('annual-chart',active.annual.map(r=>r[a]),active.annual.map(r=>r.year),$('annual-metric').selectedOptions[0].text)}
function management(){const s=systems[$('system').value];$('management-title').textContent=s[0];$('management').innerHTML=[1,3,5].map(i=>`<article><h3>${s[i]}</h3><p>${s[i+1]}</p></article>`).join('');renderSoil();renderProduction()}
function renderSoil(){if(!active)return;const soil=active.soil??[];$('soil-status').textContent=soil.length?`${soil.length}/45 mapped records`:'Not acquired';if(!soil.length){$('soil-content').innerHTML='<div class="soil-note">No soil snapshot is available at this coordinate. Weather results remain usable; soil suitability is not assessed.</div>';return}const rows=[];for(const p of ['phh2o','soc','sand','silt','clay'])for(const depth of ['0-5cm','5-15cm','15-30cm']){const r=soil.filter(x=>x.property===p&&x.depth===depth),v=s=>r.find(x=>x.statistic===s)?.value;rows.push(`<tr><td>${({phh2o:'pH in water',soc:'Organic carbon',sand:'Sand',silt:'Silt',clay:'Clay'})[p]}</td><td>${depth}</td><td>${fmt(v('mean'))} ${esc(r[0]?.unit??'')}</td><td>${fmt(v('Q0.05'))}–${fmt(v('Q0.95'))}</td></tr>`)}$('soil-content').innerHTML=($('system').value.endsWith('pots')?'<div class="soil-note">For pots, these native-soil estimates are site context only. Substrate, irrigation water and container drainage have not been assessed.</div>':'')+`<div class="table-scroll"><table><thead><tr><th>Property</th><th>Depth</th><th>Mean</th><th>5th–95th bounds</th></tr></thead><tbody>${rows.join('')}</tbody></table></div><p class="small">ISRIC SoilGrids predictions, not field measurements. Bounds describe prediction uncertainty. WCS returned geographic-grid samples; native-grid parity and field drainage remain unverified.</p>`}
const CLASSES=['Evergreen','Semi-evergreen','Deciduous'],STAGES=[['chill','Chill fulfilled'],['budbreak','Budbreak'],['flowering_start','Flowering start'],['flowering_end','Flowering end'],['harvest_start','Harvest start'],['harvest_end','Harvest end']];
const md=s=>{if(!s)return 'Unavailable';const [m,d]=s.split('-');return `${Number(d)} ${['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][Number(m)-1]}`};
const pct=v=>v===null||v===undefined?'Unavailable':`${Math.round(v*100)}%`;
function renderProduction(){if(!active)return;const p=active.production,node=$('production-content'),badge=$('production-badge');if(!p||p.status!=='available'){badge.textContent='Not available';node.innerHTML=`<div class="soil-note">${esc(p?.reason??'Production analysis is not part of this saved result.')} Annual exposure context below remains usable.</div>`;return}
const c=p.classification,cal=p.calendar,rk=p.risks,a=p.assumptions,open=$('system').value==='open_ground';badge.textContent=`${esc(p.profile)} · ${a.chill_definition==='below_7_2'?'T < 7.2°C':'0–7.2°C'} · ${a.chill_requirement_hours} h`;
const rule=r=>{const x=c[r];const counts=CLASSES.map(k=>`${k.replace('Semi-evergreen','Semi')} ${x.year_counts[k]}`).join(' · ');return `<tr><td>${r==='chill_only'?'Chill-only':'Multi-feature'}</td><td>${esc(c.mean_based[r]??'Unavailable')}</td><td>${counts}</td><td><strong>${esc(x.majority??'Unavailable')}</strong>${x.majority_share!==null&&x.majority_share!==undefined?` <span class="small">(${pct(x.majority_share)} of ${x.valid_years})</span>`:''}</td></tr>`};
const risk=r=>{const ex=Object.entries(r.exposure).map(([k,v])=>`${k.replace(/_/g,' ')}: mean ${fmt(v.mean)}, p90 ${fmt(v.p90)}`).join('; ');return `<tr><td>${r.rank}</td><td>${esc(r.label)}</td><td>${r.years_with_event} / ${r.valid_years}</td><td><strong>${pct(r.frequency)}</strong>${r.ci95?` <span class="small">${pct(r.ci95[0])}–${pct(r.ci95[1])}</span>`:''}</td><td class="small">${esc(ex)}</td></tr>`};
const seasons=p.seasons.map(s=>`<tr><td>${s.winter_year}</td><td>${esc(s.status)}</td><td>${fmt(s.chill_hours,0)}</td><td>${esc(c.per_year[s.winter_year]?.multi_feature??'—')}</td><td>${esc(s.chill_date??'—')}</td><td>${esc(s.budbreak_date??'—')}</td><td>${s.flowering?esc(s.flowering.join(' → ')):'—'}</td><td>${s.harvest?esc(s.harvest.join(' → ')):'—'}</td><td>${fmt(s.metrics.flower_freeze_days,0)}</td><td>${fmt(s.metrics.fruit_severe_heat_days,0)}</td><td>${fmt(s.metrics.harvest_rain_mm,0)}</td><td>${fmt(s.metrics.harvest_heavy_rain_days,0)}</td><td>${fmt(s.metrics.production_max_dry_days,0)}</td></tr>`).join('');
const sens=Object.entries(p.sensitivity).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${v.chill_definition==='below_7_2'?'T < 7.2°C':'0–7.2°C'}</td><td>${v.chill_requirement_hours}</td><td>${fmt(v.chill_hours_mean,0)}</td><td>${esc(v.majority_multi_feature??'Unavailable')}</td><td>${md(v.flowering_start_median)}</td><td>${md(v.harvest_start_median)}</td><td>${pct(v.flowering_freeze_frequency)}</td></tr>`).join('');
const ch=p.chill_hours;node.innerHTML=`${open?'':'<div class="soil-note">Evaluated for open field + ground. The selected growing setup keeps qualitative notes only; no tunnel or pot adjustment is applied to these results.</div>'}<div class="prod-grid"><article class="prod-panel"><span class="stamp">System hypothesis</span><div class="metric">${esc(c.multi_feature.majority??'Unavailable')}</div><p class="small">Two-thirds majority across ${c.multi_feature.valid_years} valid winters, multi-feature rule. Mean chill ${fmt(ch.mean,0)} h (${esc(a.chill_definition==='below_7_2'?'T < 7.2°C':'0–7.2°C')}), p10–p90 ${fmt(ch.p10,0)}–${fmt(ch.p90,0)} h.</p><table><thead><tr><th>Rule</th><th>From means</th><th>Per-winter counts</th><th>Majority</th></tr></thead><tbody>${rule('chill_only')}${rule('multi_feature')}</tbody></table><p class="small">Evergreen &lt;${a.evergreen_chill_max} h with warm winter months and no freezing; Deciduous ≥${a.deciduous_chill_min} h; otherwise semi-evergreen. A climate label for a chill-triggered clock, not a cultivar verdict. Evergreen-class sites need a management-anchored calendar, which is not implemented.</p></article><article class="prod-panel"><span class="stamp">Assumed calendar</span><table><thead><tr><th>Stage</th><th>Median</th><th>p10–p90</th><th>Winters</th></tr></thead><tbody>${STAGES.map(([k,l])=>`<tr><td>${l}</td><td><strong>${md(cal[k].median_date)}</strong></td><td>${md(cal[k].p10_date)} – ${md(cal[k].p90_date)}</td><td>${cal[k].n}</td></tr>`).join('')}</tbody></table><p class="small">${a.chill_requirement_hours} h chill, then ${a.gdd_to_budbreak} °C·d above ${a.gdd_base_c}°C to budbreak; flowering +${a.flowering_after_budbreak_days[0]}–${a.flowering_after_budbreak_days[1]} d; harvest +${a.harvest_after_flowering_start_days[0]}–${a.harvest_after_flowering_start_days[1]} d from flowering start. Provisional constants for a UF-type low-chill cultivar; bearing-plant cycle, not an establishment plan.</p></article></div><article class="prod-panel"><span class="stamp">Stage risks · ranked by winters with an event</span><div class="table-scroll"><table><thead><tr><th>#</th><th>Risk</th><th>Winters</th><th>Frequency · 95% CI</th><th>Exposure</th></tr></thead><tbody>${rk.ranked.map(risk).join('')}</tbody></table></div><p class="small">${esc(rk.note)} Unranked: dry spell median ${fmt(rk.unranked_exposures.production_max_dry_days.median,0)} d (p90 ${fmt(rk.unranked_exposures.production_max_dry_days.p90,0)}); disease-favourable days flowering ${fmt(rk.unranked_exposures.flowering_disease_days.mean)} / harvest ${fmt(rk.unranked_exposures.harvest_disease_days.mean)}; harvest VPD ${fmt(rk.unranked_exposures.harvest_vpd_mean_kpa.mean,2)} kPa.</p></article><details><summary>Per-winter record, sensitivity to chill definition and requirement, and what changed from the R workflow</summary><div class="table-scroll"><table><thead><tr><th>Winter</th><th>Status</th><th>Chill h</th><th>Class</th><th>Chill date</th><th>Budbreak</th><th>Flowering</th><th>Harvest</th><th>Freeze d</th><th>≥35°C d</th><th>Harvest mm</th><th>≥10 mm d</th><th>Dry spell</th></tr></thead><tbody>${seasons}</tbody></table></div><div class="table-scroll"><table><thead><tr><th>Profile</th><th>Definition</th><th>Requirement h</th><th>Mean chill</th><th>Majority</th><th>Flowering start</th><th>Harvest start</th><th>Flowering freeze</th></tr></thead><tbody>${sens}</tbody></table></div><ul class="small">${p.changes.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><ul class="small">${p.limitations.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`;CycleView.mount(node,p,{site:active.site.name,system:$('system').value});}
function render(r){active=r;$('results').hidden=false;$('location-name').textContent=r.site.name;$('coordinate-label').textContent=`${r.site.lat.toFixed(6)}, ${r.site.lon.toFixed(6)}`;const ann=r.annual,v=k=>ann.map(a=>a[k]),solar=ann.map(a=>a.solar??null);$('risk-cards').innerHTML=card('Chill',median(v('chill_hours')),'hours','Median reference-winter chill · 0–7.2°C',v('chill_hours'),1)+card('Freeze',mean(v('cold_days')),'days/yr','Mean days with minimum temperature <0°C',v('cold_days'),2)+card('Rainfall',mean(v('rain_mm')),'mm/yr','Mean annual total · not harvest rainfall',v('rain_mm'),3)+card('Heat',mean(v('hot_days')),'days/yr','Mean days with maximum temperature ≥35°C',v('hot_days'),4)+card('Dry weather',good(v('dry_spell')).length?Math.max(...good(v('dry_spell'))):null,'days','Longest within-year dry spell · rain <1 mm',v('dry_spell'),5)+card('Radiation',mean(solar),'MJ/m²/day','Mean annual daily shortwave energy',solar,6);$('availability').innerHTML=`<span>DAILY / ${r.provenance.rows} rows</span><span>HOURLY / ${good(v('chill_hours')).length?'reference data available':'not acquired'}</span><span>SOIL / ${r.soil?.length??0} records</span><span>MET CELL / ${fmt(r.provenance.sources?.[0]?.distance_km)} km from pin</span>`;$('annual-table').innerHTML='<table><thead><tr>'+['Year','Chill h','Cold days','Rain mm','Hot days','Dry spell days','Solar MJ/m²/day'].map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>'+ann.map(a=>'<tr>'+['year','chill_hours','cold_days','rain_mm','hot_days','dry_spell','solar'].map(k=>`<td>${fmt(a[k])}</td>`).join('')+'</tr>').join('')+'</tbody></table>';$('summary').innerHTML=`<p>${esc(r.site.name)} has ${fmt(mean(v('rain_mm')))} mm mean annual rainfall across ${good(v('rain_mm')).length} usable years. The longest within-year dry spell is ${fmt(good(v('dry_spell')).length?Math.max(...good(v('dry_spell'))):null)} days. These describe weather exposure, not irrigation need or yield loss.</p><p>Outdoor weather values remain unchanged across growing-system choices. Tunnel effects, soil drainage and cultivar suitability have not been calibrated.</p><p>Station comparisons have shown missed cold events in the gridded data. Zero recorded cold days is not proof of frost safety. ${r.provenance.screening?.precip_suspect_days?`This point has ${r.provenance.screening.precip_suspect_days} suspect rainfall days; affected windows are excluded.`:''}</p>`;$('provenance').innerHTML=`<p>Method: ${esc(r.method_version??'location-evidence-v1')} · Baseline 2011–2025 · UTC. Analysis ID: ${esc(r.analysis_id??'saved-snapshot')}.</p><p>NASA POWER daily meteorology: 0.5° × 0.625°; solar: 1° × 1°. Each variable retains its source grid. Values are uncorrected gridded estimates.</p><p><a href="https://power.larc.nasa.gov/docs/services/aws/" target="_blank" rel="noreferrer">NASA POWER source</a> · <a href="https://docs.isric.org/globaldata/soilgrids/" target="_blank" rel="noreferrer">SoilGrids source</a></p><pre>${esc(JSON.stringify(r.provenance.sources,null,2))}</pre>`;management();charts();$('status').textContent='Assessment ready · descriptive evidence, not a cultivar recommendation';}
async function analyze(lat,lon){if(!Number.isFinite(lat)||!Number.isFinite(lon)||lat< -90||lat>90||lon< -180||lon>180)throw Error('Enter a latitude from −90 to 90 and longitude from −180 to 180.');const request=++serial;$('error').hidden=true;$('status').textContent='Reading location evidence…';$('analyze').disabled=true;$('results').hidden=true;active=null;try{const saved=Object.values(catalog).find(r=>Math.abs(r.site.lat-lat)<1e-7&&Math.abs(r.site.lon-lon)<1e-7);let result=saved;if(!result){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),90000);try{const res=await fetch(`/api/analysis?latitude=${encodeURIComponent(lat)}&longitude=${encodeURIComponent(lon)}`,{signal:controller.signal});if(!res.ok)throw Error('The private analysis server is unavailable here. Use a saved reference location; arbitrary-coordinate analysis requires the connected local workspace.');result=await res.json();if(result.error)throw Error(result.error)}finally{clearTimeout(timer)}}if(request!==serial)return;render(result);return {location:result.site.name,status:'ready'};}catch(e){if(request===serial){$('error').textContent=e.name==='AbortError'?'Analysis timed out. No result has been substituted.':e.message;$('error').hidden=false;$('status').textContent='No assessment returned for this coordinate';}throw e;}finally{if(request===serial)$('analyze').disabled=false}}
$('location-form').addEventListener('submit',e=>{e.preventDefault();analyze(Number($('latitude').value),Number($('longitude').value)).catch(()=>{})});document.querySelectorAll('[data-site]').forEach(b=>b.onclick=()=>{const r=catalog[b.dataset.site];if(!r)return;$('latitude').value=r.site.lat;$('longitude').value=r.site.lon;analyze(r.site.lat,r.site.lon).catch(()=>{})});$('system').onchange=management;$('monthly-metric').onchange=charts;$('annual-metric').onchange=charts;let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(charts,100)});
function download(content,type,name){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.hidden=true;document.body.append(a);a.click();setTimeout(()=>{a.remove();URL.revokeObjectURL(u)},1000)}
$('export-json').onclick=()=>{
  if(!active)return;
  const view=document.querySelector('.cycle-panel')?.dataset;
  download(JSON.stringify({...active,management:systems[$('system').value][0],management_evidence:'qualitative only',
    cycle_view:view?.winter?{winter:view.winter,stage:view.stage}:null},null,2),'application/json','blueberry-assessment.json');
};
$('export').onclick=async()=>{
  if(!active)return;
  const snapshot=active,system=systems[$('system').value][0],content=$('results').cloneNode(true);
  content.querySelector('.actions')?.remove();
  content.querySelector('.cycle-stage-controls')?.remove();
  content.querySelector('.cycle-panel')?.classList.add('is-snapshot');
  const cycleIntro=content.querySelector('.cycle-header p');
  if(cycleIntro)cycleIntro.textContent='Saved cycle view. Full evidence tables follow below.';
  content.querySelectorAll('select').forEach(s=>{
    const label=document.createElement('span');
    label.textContent=$(s.id)?.selectedOptions[0]?.text??'';
    s.replaceWith(label);
  });
  content.querySelectorAll('details').forEach(d=>d.open=true);
  const css=await fetch('style.css').then(r=>r.text());
  download(`<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(snapshot.site.name)} — Blueberry assessment</title><style>${css}</style><main><p class="stamp">Historical baseline 2011–2025 · ${esc(system)} · ${esc(snapshot.analysis_id??'saved-snapshot')}</p>${content.outerHTML}</main></html>`,'text/html','blueberry-assessment.html');
};
fetch('snapshots.json').then(r=>{if(!r.ok)throw Error('Saved evidence could not load');return r.json()}).then(data=>{catalog=data.sites;return analyze(-26.312389,-50.080639)}).catch(e=>{$('error').textContent=e.message;$('error').hidden=false});
if(['127.0.0.1','localhost'].includes(location.hostname))fetch('/api/health').then(r=>r.ok?r.json():null).then(r=>{if(r?.status==='ready')$('connection').textContent='Private archive connected · coordinate lookup available'}).catch(()=>{});
if(document.modelContext?.registerTool){Promise.resolve(document.modelContext.registerTool({name:'analyze_blueberry_location',description:'Analyze a coordinate and update the visible historical climate assessment. No weather download is triggered.',inputSchema:{type:'object',properties:{latitude:{type:'number'},longitude:{type:'number'}},required:['latitude','longitude'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({latitude,longitude})=>{if(typeof latitude!=='number'||typeof longitude!=='number'||!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180)throw Error('Numeric coordinates within latitude/longitude bounds required');$('latitude').value=latitude;$('longitude').value=longitude;return analyze(latitude,longitude)}})).catch(()=>{})}
